'use strict';
const el=id=>document.getElementById(id);
const zone='America/Los_Angeles';
const dateKey=t=>new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t));
const dateText=t=>new Intl.DateTimeFormat('en-US',{timeZone:zone,month:'short',day:'numeric',year:'numeric'}).format(new Date(t));
const clock=t=>new Intl.DateTimeFormat('en-US',{timeZone:zone,hour:'numeric',minute:'2-digit',second:'2-digit',timeZoneName:'short'}).format(new Date(t));
const dollars=c=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:c%100===0?0:2}).format(c/100);
let events=new Map(), busy=false, initialized=false, latest=0, earliest=Infinity, hasOlder=false;
const expanded=new Set(), seen=new Set();
function node(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n}
function ingest(rows,updateCursors=true){let changed=false;for(const e of rows){if(!events.has(e.id)){events.set(e.id,e);changed=true}if(updateCursors){latest=Math.max(latest,e.sequence);earliest=Math.min(earliest,e.sequence)}}return changed}
function render(){
 const currentRep=el('repFilter').value;const reps=[...new Set([...events.values()].map(e=>e.rep_name))].sort();el('repFilter').replaceChildren(new Option('All reps',''),...reps.map(r=>new Option(r,r)));el('repFilter').value=currentRep;
 const q=el('search').value.trim().toLowerCase(),range=el('dateFilter').value,today=dateKey(Date.now());const start=new Date(today+'T12:00:00Z');start.setUTCDate(start.getUTCDate()-6);const week=start.toISOString().slice(0,10);
 const groups=new Map();for(const e of events.values()){if(!groups.has(e.session_id))groups.set(e.session_id,[]);groups.get(e.session_id).push(e)}
 const sessions=[...groups.entries()].map(([id,rows])=>({id,rows:rows.sort((a,b)=>b.occurred_at.localeCompare(a.occurred_at)||b.sequence-a.sequence)})).sort((a,b)=>b.rows[0].occurred_at.localeCompare(a.rows[0].occurred_at)||b.rows[0].sequence-a.rows[0].sequence);
 const frag=document.createDocumentFragment();let count=0;
 for(const {id,rows} of sessions){const head=rows[0];const matchesName=(!currentRep||head.rep_name===currentRep)&&(!q||(head.customer_label+' '+head.rep_name).toLowerCase().includes(q));const matchesDate=rows.some(e=>range==='all'||(range==='today'?dateKey(e.occurred_at)===today:dateKey(e.occurred_at)>=week));if(!matchesName||!matchesDate)continue;count++;
 const details=node('details','appointment');details.dataset.session=id;if(!seen.has(id)){seen.add(id);if(count<=3)expanded.add(id)}details.open=expanded.has(id);details.addEventListener('toggle',()=>{if(details.open){expanded.add(id);void completeSession(id)}else expanded.delete(id)});
 const summary=node('summary');const identity=node('div','appointment-identity');identity.append(node('div','customer-name',head.customer_label),node('div','rep-name',head.rep_name));const meta=node('div','session-meta');meta.append(node('div','',dateText(head.occurred_at)),node('div','',rows.length+' activit'+(rows.length===1?'y':'ies')));summary.append(identity,meta);details.append(summary);
 for(const e of rows){const row=node('div','activity-row '+e.action);const icon=node('span','event-icon',({confirmed:'✓',presented:'◷',applied:'⊕',removed:'⊖',updated:'↗'})[e.action]);icon.setAttribute('aria-hidden','true');const content=node('div');const title=node('div','activity-title');title.append(node('span','action',({confirmed:'Customer confirmed',presented:'Price first presented',applied:'Applied',removed:'Removed',updated:'Updated'})[e.action]));if(e.discount_label)title.append(document.createTextNode(' · '+e.discount_label));content.append(title);
 let detail=e.action==='confirmed'?'Signature completed · Project price '+dollars(e.total_cents):e.action==='presented'?'Retail MSRP '+dollars(e.retail_cents):e.discount_key==='dollars'?(e.action==='updated'?dollars(e.previous_value*100)+' → ':'')+dollars(e.value*100):(e.action==='updated'?e.previous_value+'% → ':'')+e.value+'% · '+dollars(e.amount_cents);title.append(document.createTextNode(' — '),node('span','activity-detail',detail));const time=node('time','event-time',dateText(e.occurred_at)+' · '+clock(e.occurred_at));time.dateTime=e.occurred_at;if(new Date(e.received_at)-new Date(e.occurred_at)>60000){time.title='Synced '+clock(e.received_at)+' on '+dateText(e.received_at);time.append(node('small','','Synced later'))}content.append(time);row.append(icon,content);details.append(row)}frag.append(details)
 }
 el('feed').replaceChildren(frag);el('feedMessage').textContent=count?'':events.size?'No matching appointments. Adjust filters or load earlier activity.':'No activity yet. Present an investment to start the activity log.';el('loadOlder').hidden=!hasOlder;
}
const completedSessions=new Set(),loadingSessions=new Set();
async function completeSession(id){if(completedSessions.has(id)||loadingSessions.has(id))return;loadingSessions.add(id);try{let offset=0,changed=false;while(true){const rows=await Activity.request('?select=*&session_id=eq.'+encodeURIComponent(id)+'&order=sequence.asc&limit=1000&offset='+offset);changed=ingest(rows,false)||changed;if(rows.length<1000)break;offset+=1000}completedSessions.add(id);if(changed)render()}catch{}finally{loadingSessions.delete(id)}}
async function refresh(){if(busy)return;busy=true;try{let changed=false;if(!initialized){const rows=await Activity.request('?select=*&order=sequence.desc&limit=500');changed=ingest(rows);hasOlder=rows.length===500;initialized=true}else{let more=true;while(more){const rows=await Activity.request('?select=*&sequence=gt.'+latest+'&order=sequence.asc&limit=1000');changed=ingest(rows)||changed;more=rows.length===1000}}if(changed||!el('feed').children.length)render();el('connection').textContent='Live activity';el('connection').classList.add('connected');el('connection').title='Last checked '+clock(Date.now())}catch{el('connection').textContent='Reconnecting…';el('connection').classList.remove('connected');if(!initialized)el('feedMessage').textContent='Unable to load activity. Retrying automatically.'}finally{busy=false}}
el('loadOlder').onclick=async()=>{el('loadOlder').disabled=true;try{const rows=await Activity.request('?select=*&sequence=lt.'+earliest+'&order=sequence.desc&limit=500');ingest(rows);hasOlder=rows.length===500;render()}catch{el('feedMessage').textContent='Could not load earlier activity. Please try again.'}finally{el('loadOlder').disabled=false}};
for(const id of ['search','repFilter','dateFilter'])el(id).addEventListener(id==='search'?'input':'change',render);
addEventListener('online',()=>void refresh());document.addEventListener('visibilitychange',()=>{if(!document.hidden)void refresh()});setInterval(()=>{if(!document.hidden)void refresh()},3000);void refresh();
